def _has_attention_status(dashboard_frame: pd.DataFrame) -> bool:
    frame = _finalize_dashboard_frame(dashboard_frame)
    if frame.empty:
        return False
    active = frame.loc[
        (frame["status"] != "MISSING")
        | (pd.to_numeric(frame.get("actionable_warning_count", 0), errors="coerce").fillna(0) > 0)
        | (pd.to_numeric(frame.get("blocking_error_count", 0), errors="coerce").fillna(0) > 0)
        | (pd.to_numeric(frame.get("active_snapshot_warning_count", 0), errors="coerce").fillna(0) > 0)
        | (pd.to_numeric(frame.get("active_snapshot_error_count", 0), errors="coerce").fillna(0) > 0)
    ]
    if active.empty:
        return False
    totals = _warning_actionability_totals(active)
    if totals["blocking_error_count"] > 0 or totals["actionable_warning_count"] > 0:
        return True
    if (
        totals["expected_reviewable_warning_count"] > 0
        or totals["expected_demo_warning_count"] > 0
        or totals["stale_warning_count"] > 0
    ):
        return False
    statuses = set(active["status"].astype(str).str.upper())
    if statuses.intersection({"FAIL", "WARN"}):
        return True
    error_count = int(pd.to_numeric(active["error_count"], errors="coerce").fillna(0).sum())
    return error_count > 0


def _component_has_only_non_actionable_warnings(dashboard_frame: pd.DataFrame, component: str) -> bool:
    frame = _finalize_dashboard_frame(dashboard_frame)
    rows = frame.loc[frame["component"] == component]
    if rows.empty:
        return False
    row = rows.iloc[0].to_dict()
    if _string_or_empty(row.get("status")) != "WARN":
        return False
    blocking = _int_or_zero(row.get("blocking_error_count"))
    actionable = _int_or_zero(row.get("actionable_warning_count"))
    expected_reviewable = _int_or_zero(row.get("expected_reviewable_warning_count"))
    expected = _int_or_zero(row.get("expected_demo_warning_count"))
    stale = _int_or_zero(row.get("stale_warning_count"))
    return blocking == 0 and actionable == 0 and (expected_reviewable > 0 or expected > 0 or stale > 0)


def _component_status(by_component: dict[str, dict[str, Any]], component: str) -> str:
    row = by_component.get(component, {})
    return _string_or_empty(row.get("status")) or "MISSING"


def _linked_snapshot_quality_status_from_frame(frame: pd.DataFrame) -> str:
    finalized = _finalize_dashboard_frame(frame)
    rows = finalized.loc[finalized["component"] == "SNAPSHOT_QUALITY"]
    if not rows.empty:
        linked = _string_or_empty(rows.iloc[0].get("linked_snapshot_quality_status"))
        if linked:
            return linked
    return ""


def _active_snapshot_chain_from_frame(frame: pd.DataFrame) -> str:
    finalized = _finalize_dashboard_frame(frame)
    rows = finalized.loc[finalized["component"] == "SNAPSHOT_QUALITY"]
    if not rows.empty:
        chain = _string_or_empty(rows.iloc[0].get("active_snapshot_chain"))
        if chain:
            return chain
    return ""


def _sum_int_column(frame: pd.DataFrame, column: str) -> int:
    if frame.empty or column not in frame.columns:
        return 0
    return int(pd.to_numeric(frame[column], errors="coerce").fillna(0).sum())


def _latest_decision_date(frame: pd.DataFrame) -> str:
    dates = sorted(_date_string(value) for value in frame.get("decision_date", pd.Series(dtype="object")).tolist() if _date_string(value))
    return dates[-1] if dates else ""


def _latest_universe_name(frame: pd.DataFrame) -> str:
    values = sorted(_string_or_empty(value) for value in frame.get("universe_name", pd.Series(dtype="object")).tolist() if _string_or_empty(value))
    return values[-1] if values else ""


def _dashboard_warnings(dashboard_frame: pd.DataFrame, workflow_stage: str) -> list[str]:
    warnings = []
    totals = _warning_actionability_totals(dashboard_frame)
    if (
        workflow_stage == "LOCAL_RESEARCH_NEEDS_ATTENTION"
        and totals["blocking_error_count"] == 0
        and totals["actionable_warning_count"] == 0
        and (
            totals["expected_reviewable_warning_count"] > 0
            or totals["expected_demo_warning_count"] > 0
            or totals["stale_warning_count"] > 0
        )
    ):
        warnings.append(
            "Only expected reviewable, demo, or stale artifact warnings were classified for the active workflow chain."
        )
    elif workflow_stage != "LOCAL_RESEARCH_WORKFLOW_COMPLETE":
        warnings.append(f"Workflow stage is {workflow_stage}; manual action is still needed.")
    failing = dashboard_frame.loc[dashboard_frame["status"] == "FAIL"] if not dashboard_frame.empty else pd.DataFrame()
    for row in failing.to_dict("records"):
        warnings.append(f"{row['component']} status is FAIL.")
    return warnings


def _warning_actionability_totals(dashboard_frame: pd.DataFrame) -> dict[str, int]:
    frame = _deduped_actionability_frame(_finalize_dashboard_frame(dashboard_frame))
    totals = {
        "total_warning_count": 0,
        "expected_reviewable_warning_count": 0,
        "expected_demo_warning_count": 0,
        "stale_warning_count": 0,
        "actionable_warning_count": 0,
        "blocking_error_count": 0,
    }
    if frame.empty:
        return totals
    for key in totals:
        if key in frame.columns:
            totals[key] = int(pd.to_numeric(frame[key], errors="coerce").fillna(0).sum())
    return totals


def _only_stale_pre_paper_fail(frame: pd.DataFrame, actionability: dict[str, int]) -> bool:
    finalized = _finalize_dashboard_frame(frame)
    failing = finalized.loc[finalized["status"] == "FAIL"]
    if failing.empty:
        return False
    stale_pre_paper_components = {
        "MARKET_UPDATE_HANDOFF_STATUS",
        "HISTORICAL_BACKFILL_STATUS",
        "MARKET_CACHE_EXPORT_POLICY_STATUS",
        "MARKET_CACHE_EXPORT_STATUS",
        "ADVISORY_PROFILE_CALIBRATION_STATUS",
        "SIGNAL_ADVISORY_STATUS",
        "SINGLE_SYMBOL_ADVISORY_STATUS",
        "SINGLE_SYMBOL_ADVISORY_ANSWER_STATUS",
        "ADVISORY_CONVERSATION_STATUS",
        "PIT_UNIVERSE_EVIDENCE_COMPLETION_HELPER_STATUS",
    }
    return (
        set(failing["component"].astype(str)).issubset(stale_pre_paper_components)
        and actionability.get("blocking_error_count", 0) == 0
        and actionability.get("actionable_warning_count", 0) == 0
        and actionability.get("stale_warning_count", 0) > 0
    )


def _deduped_actionability_frame(frame: pd.DataFrame) -> pd.DataFrame:
    if frame.empty:
        return frame
    paper_rows = frame.loc[frame["component"] == "PAPER_WORKFLOW_STATUS"]
    if paper_rows.empty:
        return frame
    paper_row = paper_rows.iloc[0]
    has_paper_counts = any(_int_or_zero(paper_row.get(key)) for key in _actionability_count_keys())
    if not has_paper_counts:
        return frame
    paper_workflow_scope = {
        "CURRENT_CANDIDATES",
        "CURRENT_CANDIDATE_HEALTH",
        "SIGNAL_ADVISORY_STATUS",
        "CURRENT_TO_PAPER_HANDOFF",
        "CURRENT_TO_PAPER_REVIEW_HANDOFF",
        "REVIEW_TEMPLATE_HEALTH",
        "PAPER_REVIEW",
        "DAILY_PAPER",
        "RECONCILIATION",
    }
    mask = ~frame["component"].isin(paper_workflow_scope)
    return frame.loc[mask].reset_index(drop=True)


def _metadata_paths(root: Path, filename: str, excluded_parts: set[str] | None = None) -> list[Path]:
    if not root.exists():
        return []
    excluded = excluded_parts or set()
    paths = []
    for path in root.rglob(filename):
        relative_parts = set(path.relative_to(root).parts[:-1])
        if relative_parts.intersection(excluded):
            continue
        paths.append(path)
    return sorted(paths)


def _load_json_or_none(path: Path) -> dict[str, Any] | None:
    if not path.exists():
        return None
    try:
        payload = json.loads(path.read_text(encoding="utf-8"))
    except (OSError, json.JSONDecodeError):
        return None
    return payload if isinstance(payload, dict) else None


def _first_csv_record(path_value: Any) -> dict[str, Any]:
    records = _csv_records(path_value)
    return records[0] if records else {}


def _csv_records(path_value: Any) -> list[dict[str, Any]]:
    path_text = _string_or_empty(path_value)
    if not path_text:
        return []
    path = Path(path_text)
    if not path.exists():
        return []
    try:
        return pd.read_csv(path, dtype=str, keep_default_na=False).fillna("").to_dict("records")
    except Exception:
        return []


def _output_files(metadata: dict[str, Any]) -> dict[str, Any]:
    output_files = metadata.get("output_files")
    return output_files if isinstance(output_files, dict) else {}


def _metadata_for_row(row: dict[str, Any]) -> dict[str, Any]:
    path_text = _string_or_empty(row.get("metadata_path"))
    if not path_text:
        return {}
    return _load_json_or_none(Path(path_text)) or {}


def _daily_reviewed_decisions_path(metadata: dict[str, Any]) -> str:
    output_files = _output_files(metadata)
    return _string_or_empty(metadata.get("reviewed_decisions_path")) or _string_or_empty(
        output_files.get("reviewed_decisions")
    )


def _artifact_id_from_path(value: Any) -> str:
    text = _string_or_empty(value)
    if not text:
        return ""
    path = Path(text)
    if path.name == "metadata.json":
        return path.parent.name
    if path.name:
        return path.parent.name
    return ""


def _paths_match(left: Any, right: Any) -> bool:
    left_keys = _path_keys(left)
    right_keys = _path_keys(right)
    return bool(left_keys and right_keys and left_keys.intersection(right_keys))


def _path_keys(value: Any) -> set[str]:
    text = _string_or_empty(value)
    if not text:
        return set()
    normalized = text.replace("\\", "/").lower()
    keys = {normalized}
    try:
        keys.add(str(Path(text).resolve(strict=False)).replace("\\", "/").lower())
    except (OSError, RuntimeError):
        pass
    return keys


def _latest_record(frame: pd.DataFrame) -> dict[str, Any]:
    sortable = frame.copy(deep=True)
    sortable["_sort_date"] = sortable["decision_date"].map(lambda value: _date_string(value))
    sortable["_sort_created"] = sortable["created_at"].map(_string_or_empty)
    sortable = sortable.sort_values(
        ["_sort_date", "_sort_created", "latest_artifact_id", "metadata_path"],
        na_position="last",
    )
    return sortable.iloc[-1].drop(labels=["_sort_date", "_sort_created"], errors="ignore").to_dict()


def _latest_reconciliation_record(frame: pd.DataFrame) -> dict[str, Any]:
    active_rows = [row for row in frame.to_dict("records") if not _reconciliation_is_diagnostic(row)]
    if active_rows:
        return _latest_record(pd.DataFrame(active_rows))
    return _latest_record(frame)


def _reconciliation_is_diagnostic(row: dict[str, Any]) -> bool:
    if _string_or_empty(row.get("component")) != "RECONCILIATION":
        return False
    metadata = _metadata_for_row(row)
    return _string_or_empty(metadata.get("artifact_scope")).lower() == "diagnostic" or metadata.get("diagnostic_artifact") is True


def _finalize_scan_frame(frame: pd.DataFrame) -> pd.DataFrame:
    scan = frame.copy(deep=True)
    columns = DASHBOARD_COLUMNS + ["created_at"]
    for column in columns:
        if column not in scan.columns:
            scan[column] = ""
    if scan.empty:
        return scan[columns]
    return scan[columns].sort_values(["workflow_area", "component", "decision_date", "created_at", "latest_artifact_id"], na_position="last").reset_index(drop=True)


def _finalize_dashboard_frame(frame: pd.DataFrame) -> pd.DataFrame:
    dashboard = frame.copy(deep=True)
    for column in DASHBOARD_COLUMNS:
        if column not in dashboard.columns:
            dashboard[column] = ""
    if dashboard.empty:
        return dashboard[DASHBOARD_COLUMNS]
    return dashboard[DASHBOARD_COLUMNS].sort_values(["component"], key=lambda series: series.map(_component_order)).reset_index(drop=True)


def _component_order(component: Any) -> int:
    text = _string_or_empty(component)
    return COMPONENTS.index(text) if text in COMPONENTS else len(COMPONENTS)


def _export_dataframe(frame: pd.DataFrame, path: Path) -> None:
    export = _sanitize_dataframe_for_export(frame)
    path.parent.mkdir(parents=True, exist_ok=True)
    export.to_csv(path, index=False)


def _sanitize_dataframe_for_export(frame: pd.DataFrame) -> pd.DataFrame:
    export = frame.copy(deep=True)
    for column in export.columns:
        if pd.api.types.is_datetime64_any_dtype(export[column]):
            export[column] = export[column].dt.strftime("%Y-%m-%d %H:%M:%S")
        elif export[column].dtype == "object":
            export[column] = export[column].map(_cell_to_export_value)
    return export


def _cell_to_export_value(value: Any) -> Any:
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(_json_safe(value), sort_keys=True)
    if isinstance(value, (pd.Timestamp, Path)):
        return str(value)
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    return value


def _markdown_table(frame: pd.DataFrame, columns: list[str], max_rows: int = 50) -> str:
    available = [column for column in columns if column in frame.columns]
    if frame.empty or not available:
        return "_No rows._"
    table = frame[available].head(max_rows).copy()
    rows = [
        "| " + " | ".join(available) + " |",
        "| " + " | ".join("---" for _ in available) + " |",
    ]
    for record in table.to_dict("records"):
        rows.append("| " + " | ".join(_format_markdown_value(record[column]) for column in available) + " |")
    return "\n".join(rows)


def _warnings_section(warnings: list[str]) -> str:
    if not warnings:
        return "- None"
    return "\n".join(f"- {warning}" for warning in warnings)


def _format_markdown_value(value: Any) -> str:
    if isinstance(value, float):
        if pd.isna(value):
            return ""
        return f"{value:.6f}"
    if isinstance(value, (dict, list, tuple)):
        return json.dumps(_json_safe(value), sort_keys=True).replace("|", "\\|")
    if isinstance(value, (pd.Timestamp, Path)):
        return str(value)
    if value is None:
        return ""
    try:
        if pd.isna(value):
            return ""
    except (TypeError, ValueError):
        pass
    return str(value).replace("|", "\\|").replace("\n", " ")


def _resolve_settings(
    config: Settings | LocalResearchDashboardSettings | dict[str, Any] | str | Path | None,
) -> tuple[Settings, LocalResearchDashboardSettings]:
    if config is None:
        project = load_settings(Path("config/default.yaml"))
        return project, project.local_research_dashboard
    if isinstance(config, Settings):
        return config, config.local_research_dashboard
    if isinstance(config, (str, Path)):
        project = load_settings(Path(config))
        return project, project.local_research_dashboard
    project = load_settings(Path("config/default.yaml"))
    if isinstance(config, LocalResearchDashboardSettings):
        return project, config
    if isinstance(config, dict):
        payload = dict(project.local_research_dashboard.model_dump())
        for key, value in config.items():
            if key == "local_research_dashboard" and isinstance(value, dict):
                payload.update(value)
            elif key in payload:
                payload[key] = value
        return project, LocalResearchDashboardSettings(**payload)
    raise TypeError("config must be Settings, LocalResearchDashboardSettings, dict, path, or None")


def _date_string(value: Any) -> str:
    if not _present(value):
        return ""
    timestamp = pd.Timestamp(value)
    if pd.isna(timestamp):
        return ""
    return str(timestamp.date())


def _int_or_zero(value: Any) -> int:
    if not _present(value):
        return 0
    try:
        return int(float(value))
    except (TypeError, ValueError):
        return 0


def _bool_from_text(value: Any) -> bool:
    text = _string_or_empty(value).lower()
    return text in {"1", "true", "yes", "y"}


def _present(value: Any) -> bool:
    if value is None:
        return False
    try:
        if pd.isna(value):
            return False
    except (TypeError, ValueError):
        pass
    return str(value).strip() != ""


def _string_or_empty(value: Any) -> str:
    return str(value).strip() if _present(value) else ""


def _hash_payload(payload: dict[str, Any], length: int) -> str:
    encoded = json.dumps(_json_safe(payload), sort_keys=True, separators=(",", ":")).encode("utf-8")
    return hashlib.sha256(encoded).hexdigest()[:length]


def _json_safe(value: Any) -> Any:
    if isinstance(value, dict):
        return {str(key): _json_safe(item) for key, item in value.items()}
    if isinstance(value, (list, tuple, set)):
        return [_json_safe(item) for item in value]
    if isinstance(value, pd.Timestamp):
        if pd.isna(value):
            return None
        return value.isoformat()
    if isinstance(value, Path):
        return str(value)
    try:
        if pd.isna(value):
            return None
    except (TypeError, ValueError):
        pass
    return value
